import type { BrowserPage, BrowserSession } from "../../browser/xe-browser-session.ts";

export type MatrixKind = "ordinary" | "challenge";
export type MatrixCase = {
  name: string;
  kind: MatrixKind;
  html: string;
  document: "search" | "detail";
  url: string;
  expectedId?: string;
};

const searchUrl = "http://127.0.0.1:8080/page/1";
const detailUrl = "http://127.0.0.1:8080/detail/101";

function encoded(value: object): string {
  return '<div data-json-data="' +
    JSON.stringify(value).replaceAll("&", "&amp;").replaceAll('"', "&quot;") +
    '"></div>';
}

function search(description?: string): string {
  return encoded({
    results: description ? [{ id: "101", url: detailUrl, price: 100, surface: 50, description }] : [],
    selected_values: {
      transaction_name: "buy",
      selected_locations: [{ geo_place_id: "fixture-place" }],
      pagination: { current_page: 1, total_pages: 1 },
      page_url: searchUrl,
    },
  });
}

function detail(description?: string): string {
  return encoded({
    results: [{ id: "101", url: detailUrl, price: 100, surface: 50, description }],
  });
}

const ordinaryDescriptions = [
  "Apartment near the Cloudflare office.",
  "The apartment presents a renovation challenge and an entrance turnstile.",
  "A security check at the main entrance is included in the condominium service.",
  "The previous tenant reports a human verification required sign next to the entrance turnstile.",
];

export const ordinaryCases: MatrixCase[] = [
  { name: "detail-attribute-office", kind: "ordinary", document: "detail", url: detailUrl, expectedId: "101", html: detail(ordinaryDescriptions[0]) },
  { name: "detail-raw-office", kind: "ordinary", document: "detail", url: detailUrl, expectedId: "101", html: JSON.stringify({ results: [{ id: "101", url: detailUrl, price: 100, surface: 50, description: ordinaryDescriptions[0] }] }) },
  { name: "detail-visible-office", kind: "ordinary", document: "detail", url: detailUrl, expectedId: "101", html: detail(ordinaryDescriptions[0]) + "<p>" + ordinaryDescriptions[0] + "</p>" },
  { name: "detail-renovation-turnstile", kind: "ordinary", document: "detail", url: detailUrl, expectedId: "101", html: detail(ordinaryDescriptions[1]) },
  { name: "detail-visible-security", kind: "ordinary", document: "detail", url: detailUrl, expectedId: "101", html: detail() + "<p>" + ordinaryDescriptions[2] + "</p>" },
  { name: "detail-visible-sign", kind: "ordinary", document: "detail", url: detailUrl, expectedId: "101", html: detail() + "<p>" + ordinaryDescriptions[3] + "</p>" },
  { name: "search-office", kind: "ordinary", document: "search", url: searchUrl, html: search(ordinaryDescriptions[0]) },
  { name: "search-inert-application-json", kind: "ordinary", document: "search", url: searchUrl, html: search() + '<script type="application/json">{"description":"The concierge documents human verification for visitor badges."}</script>' },
];

const challengeFragments = [
  "<main>captcha human verification</main>",
  "<section>Human verification required</section>",
  "<p>Please verify you are human</p>",
  "<section>Human verification required. Please verify you are human to continue.</section>",
  "<!doctype html><html><head><title>Property search</title></head><body><header>Available homes</header><div><main>Human verification required</main></div></body></html>",
  "<p>Human verification required!</p>",
  "<section>Access denied. Verify you are human to continue.</section>",
  '<div class="cf-turnstile" data-sitekey="synthetic">Verify you are human</div>',
  '<form action="/verify-human"><button>Verify you are human</button></form>',
];

export const challengeCases: MatrixCase[] = challengeFragments.map((fragment, index) => ({
  name: "challenge-" + String(index + 1),
  kind: "challenge",
  document: index === 7 ? "detail" : "search",
  url: index === 7 ? detailUrl : searchUrl,
  expectedId: index === 7 ? "101" : undefined,
  html: (index === 7 ? detail() : search()) + fragment,
}));

export const allMatrixCases = [...ordinaryCases, ...challengeCases];

export function createSyntheticSession(html: string): BrowserSession {
  let currentUrl = "about:blank";
  const navigations: string[] = [];
  const page: BrowserPage = {
    url: () => currentUrl,
    context: () => context,
    goto: async (url: string) => {
      currentUrl = url;
      navigations.push(url);
      return { status: () => 200, headers: async () => ({}), url: () => url };
    },
    content: async () => html,
    isClosed: () => false,
    close: async () => undefined,
    locator: () => ({ click: async () => undefined }),
  };
  const context = {
    pages: () => [page],
    newPage: async () => page,
    route: async () => undefined,
    close: async () => undefined,
    cookies: async () => [],
    clearCookies: async () => undefined,
  };
  return { browser: null, context, page, owned: false };
}

import { expect, test } from "vitest";
import { acceptsCaptchaDocument } from "../browser/captcha-document.ts";
import { startControlServer } from "./helpers/attica-control-harness.js";
import {
  allMatrixCases,
  challengeCases,
  createSyntheticSession,
  ordinaryCases,
} from "./fixtures/attica-captcha-matrix.ts";

test("bounded offline CAPTCHA matrix preserves all ordinary encodings and challenge boundaries", () => {
  for (const item of allMatrixCases) {
    const accepted = acceptsCaptchaDocument({
      kind: item.document,
      expectedUrl: item.url,
      currentUrl: item.url,
      expectedId: item.expectedId,
      html: item.html,
    });
    expect(accepted, item.name).toBe(item.kind === "ordinary");
  }
  expect(ordinaryCases).toHaveLength(8);
  expect(challengeCases).toHaveLength(9);
});

async function waitForPause(
  harness: {
    getStore(): { loadPause(): { pauseType?: string | null } };
    sleep(ms: number): Promise<void>;
  },
): Promise<void> {
  for (let attempt = 0; attempt < 100; attempt += 1) {
    if (harness.getStore().loadPause().pauseType === "captcha") return;
    await harness.sleep(10);
  }
  throw new Error("matrix timeout waiting for CAPTCHA pause");
}

test("real control HTTP path pauses at search and persists across reopen", async () => {
  const session = createSyntheticSession(challengeCases[0].html);
  const harness = await startControlServer({
    prefix: "attica-captcha-matrix-search-",
    session,
  });

  try {
    const started = await harness.httpRequest("POST", "/api/start", {
      target: harness.fixtureOrigin + "/page/1",
      maxPages: 1,
    });
    expect(started.status).toBe(202);
    await waitForPause(harness);
    expect(harness.getStore().loadPause().pauseType).toBe("captcha");
    expect(harness.getNavigationHistory().some((entry) => entry.url.endsWith("/page/1"))).toBe(true);

    const reopened = await harness.restartOnSameRoot();
    try {
      expect(reopened.store.loadPause().pauseType).toBe("captcha");
      const blocked = await reopened.httpRequest("POST", "/api/resume", {});
      expect(blocked.status).toBe(425);
      expect(reopened.getNavigationCount()).toBe(0);
    } finally {
      await new Promise<void>((resolve) => reopened.server.close(() => resolve()));
    }
  } finally {
    await harness.cleanup();
  }
});

test("real control HTTP path reaches detail CAPTCHA and verification does not navigate", async () => {
  const harness = await startControlServer({
    prefix: "attica-captcha-matrix-detail-",
    fakeSessionOptions: { detailMode: "captcha", completeListings: false },
  });

  try {
    const started = await harness.httpRequest("POST", "/api/start", {
      target: harness.fixtureOrigin + "/page/1",
      maxPages: 1,
    });
    expect(started.status).toBe(202);
    await waitForPause(harness);
    const before = harness.getNavigationCount();
    const refused = await harness.httpRequest("POST", "/api/verify-access", {});
    expect(refused.status).toBe(403);
    expect(harness.getStore().loadPause().pauseType).toBe("captcha");
    expect(harness.getNavigationCount()).toBe(before);

    harness.getFakeSession()._setDetailMode("normal");
    const verified = await harness.httpRequest("POST", "/api/verify-access", {});
    expect(verified.status).toBe(200);
    expect(harness.getNavigationCount()).toBe(before);
    const resumed = await harness.httpRequest("POST", "/api/resume", {});
    expect(resumed.status).toBe(202);
  } finally {
    await harness.cleanup();
  }
});
